	}
	web := m.updates.status(docker.Container{ID: "c1", Image: "nginx:latest"})
	if web.Kind != imageupdate.NewBuild || !strings.Contains(web.Label(), "new build") {
		t.Errorf("web = %+v, want a new build", web)
